using System;
using System.Collections.Generic;
using System.Globalization;
using UnityEngine;
using UnityEngine.Scripting;

namespace SurvivorCommunity
{
    /// <summary>
    /// The survivor snapshot (Config/XUi_InGame/windows.xml windowScSnapshot, generated by Tools/generate_snapshot_ui.py,
    /// in the vanilla "dialog" group): while the player talks to a survivor, a card on the left of the screen - clear of
    /// the face the dialog camera centres on and of the spoken line at the bottom - with their name and role, portrait,
    /// health, stamina, mood, traits and skills (the user's design, 2026-10-07, after State of Decay 2's card).
    ///
    /// A member shows their registry record. Anyone else shows their ScProfile (rolled here, on the host, the first time
    /// they are talked to, and kept when they join); their traits read "????" until their favour is done. Stamina is
    /// shown from Cardio (NPCs have no stamina stat). Nothing shows for traders, raiders or other NPCs trust does not
    /// cover, and nothing for a stranger with no profile yet (a multiplayer client: profiles are rolled on the host, so
    /// a client sees a stranger's card once the host has talked to them). Every binding is non-null from the
    /// constructor: bindings are evaluated while the XML is parsed.
    /// </summary>
    [Preserve]
    public class XUiC_ScSnapshot : XUiController
    {
        public const int TraitRows = 3;
        public const int SkillRows = 5;        // the four core skills and the specialty
        private const float RefreshSeconds = 0.25f;
        private const string StarOn = "255,255,255,255";
        private const string StarOff = "255,255,255,70";   // dim by alpha: AshfallUI keeps its brass star only for a tint at least 35% bright

        private XUiV_Texture portrait;
        private float nextRefresh;
        private int shownId = -1, shownPortraitVersion = -1;
        private Member shown;                  // the record on show: a member's, or a profile wrapped as one
        private bool visible, hasPortrait, traitsKnown;
        private string name = "", role = "", health = "0", healthMax = "0", stamina = "0", staminaMax = "0";
        private string moodWord = "", moodIcon = "scui_mood_content", moodColor = "255,255,255,255", specName = "", specIcon = "ui_game_symbol_perk";
        private bool specVisible;
        private readonly string[] traits = new string[TraitRows];
        private readonly bool[] traitVisible = new bool[TraitRows];
        private readonly int[] stars = new int[SkillRows];

        public XUiC_ScSnapshot()
        {
            for (int i = 0; i < TraitRows; i++) traits[i] = "";
        }

        public override void Init()
        {
            base.Init();
            XUiController c = GetChildById("snapPortrait");
            portrait = c != null ? c.ViewComponent as XUiV_Texture : null;
            if (portrait != null) ScPortraits.Wanted = true;
        }

        public override void OnOpen()
        {
            base.OnOpen();
            shownId = -1;
            nextRefresh = 0f;
        }

        public override void OnClose()
        {
            base.OnClose();
            Drop();
            visible = false;
        }

        public override void Update(float _dt)
        {
            base.Update(_dt);
            float now = Time.unscaledTime;
            if (now < nextRefresh) return;
            nextRefresh = now + RefreshSeconds;
            try
            {
                if (Recompute()) RefreshBindings();
            }
            catch (Exception e)
            {
                ScLog.Once("snapshot", e);
            }
        }

        /// <summary>The NPC being talked to: the dialog's respondent (SCore sets it as vanilla does).</summary>
        private EntityAlive Respondent()
        {
            return xui != null && xui.Dialog != null ? xui.Dialog.Respondent : null;
        }

        private bool Recompute()
        {
            EntityAlive npc = Respondent();
            bool changed = false;
            Member member = npc != null ? ScRegistry.GetMember(npc.entityId) : null;
            // a member, a stranger the trust rules cover, or one of an enclave's or a drifter band's people (E2, E13a: their
            // profile is stamped from their record, so the card is the same on every visit; ScTrust.Subject leaves them out
            // for their hits only)
            bool show = npc != null && !npc.IsDead() && (member != null || ScTrust.Subject(npc) || ScEnclavePeople.IsEnclaveNpc(npc)
                                                         || (ScBands.IsBandNpc(npc) && !ScXnpc.IsRaider(npc)));
            if (show && (npc.entityId != shownId || shown == null))
            {
                if (shownId >= 0 && shownId != npc.entityId) ScPortraits.Forget(shownId);
                shownId = npc.entityId;
                shownPortraitVersion = -1;
                if (member == null) ScProfile.Ensure(npc);
                shown = member ?? WithLook(ScProfile.Read(npc), npc);
                changed = true;
            }
            else if (show && member != null && !ReferenceEquals(member, shown))
            {
                shown = member;   // they joined while the dialog was open
                changed = true;
            }
            // no card: not someone it is for, or no profile to show (a client before the host rolled one, a failed roll)
            if (!show || shown == null)
            {
                changed = visible;
                visible = false;
                Drop();
                return changed;
            }
            if (!visible) changed = true;
            visible = true;

            changed |= Set(ref name, ScCommunity.DisplayName(npc));
            changed |= Set(ref role, XUiC_ScCommunity.RoleText(shown));
            changed |= Set(ref health, Num(npc.Health));
            changed |= Set(ref healthMax, Num(npc.GetMaxHealth()));
            int maxStamina = 100 + 10 * (shown.Stars(Skill.Cardio) - 1);   // display only: NPCs have no stamina stat
            changed |= Set(ref stamina, Num(maxStamina));
            changed |= Set(ref staminaMax, Num(maxStamina));
            changed |= Set(ref moodWord, Capital(ScMorale.MoodWord(shown.Mood)));
            changed |= Set(ref moodIcon, MoodIcon(shown.Mood));
            changed |= Set(ref moodColor, MoodColor(shown.Mood));

            // traits: a member's are known, and a former member's; anyone else's once their favour is done (Friendly); an
            // enclave person's once their enclave is Friendly or better (E2)
            bool known = member != null || ScProfile.Known(npc)
                         || (ScCommunity.LocalPlayer != null && ScTrust.Level(npc, ScCommunity.LocalPlayer) == Trust.Friendly)
                         || ScEnclavePeople.TraitsKnown(npc);
            if (known != traitsKnown) { traitsKnown = known; changed = true; }
            for (int i = 0; i < TraitRows; i++)
            {
                bool has = i < shown.Traits.Count;
                if (traitVisible[i] != has) { traitVisible[i] = has; changed = true; }
                changed |= Set(ref traits[i], has ? (known ? ScTraits.Display(shown.Traits[i]) : Localization.Get("scSnapUnknownTrait")) : "");
            }

            for (int i = 0; i < Member.SkillCount; i++) changed |= SetInt(ref stars[i], shown.Stars((Skill)i));
            bool spec = shown.Specialty != Specialty.None;
            if (spec != specVisible) { specVisible = spec; changed = true; }
            changed |= SetInt(ref stars[SkillRows - 1], spec ? Math.Max(1, Math.Min(Member.MaxStars, shown.SpecLevel)) : 0);
            changed |= Set(ref specName, spec ? Localization.Get(ScNames.LocKey(shown.Specialty)) : "");
            changed |= Set(ref specIcon, spec ? XUiC_ScCommunity.SpecIcon(shown.Specialty) : "ui_game_symbol_perk");

            changed |= ApplyPortrait();
            return changed;
        }

        /// <summary>Nothing on show: forget a stranger's picture and start from scratch next time.</summary>
        private void Drop()
        {
            if (portrait != null && portrait.Texture != null) portrait.Texture = null;
            if (shownId >= 0) ScPortraits.Forget(shownId);
            shown = null;
            shownId = -1;
        }

        /// <summary>A profile read from the body, given what ScPortraits needs to shoot the picture.</summary>
        private static Member WithLook(Member p, EntityAlive npc)
        {
            if (p == null) return null;
            p.Class = ScCommunity.ClassName(npc);
            p.Name = ScCommunity.DisplayName(npc);
            p.Born = npc.WorldTimeBorn;
            p.Look = ScLooks.Get(npc);
            return p;
        }

        private bool ApplyPortrait()
        {
            if (portrait == null) return false;
            if (shownPortraitVersion == ScPortraits.Version && ReferenceEquals(portrait.Texture, Current())) return false;
            shownPortraitVersion = ScPortraits.Version;
            Texture2D t = Current();
            // by reference: Unity's == calls a destroyed texture null, and the view would keep drawing it
            if (!ReferenceEquals(portrait.Texture, t)) portrait.Texture = t;
            bool has = t != null;
            if (has == hasPortrait) return false;
            hasPortrait = has;
            return true;
        }

        private Texture2D Current()
        {
            return shown != null ? ScPortraits.Get(shown) : null;
        }

        private static string MoodIcon(int mood)
        {
            if (mood >= 75) return "scui_mood_happy";
            if (mood >= 50) return "scui_mood_content";
            if (mood >= 25) return "scui_mood_uneasy";
            return "scui_mood_miserable";
        }

        /// <summary>ScMorale.MoodWord's bands, colored as the Home Status panel colors them (ScMorale.MoodColor: green while
        /// content or happy, amber while uneasy, red while miserable).</summary>
        private static string MoodColor(int mood)
        {
            return ScMorale.MoodColor(mood);
        }

        private static string Capital(string s)
        {
            if (string.IsNullOrEmpty(s)) return "";
            return char.ToUpper(s[0], CultureInfo.CurrentCulture) + s.Substring(1);
        }

        private static string Num(float v) { return Mathf.RoundToInt(v).ToString(CultureInfo.InvariantCulture); }

        private static bool Set(ref string field, string value)
        {
            if (value == null) value = "";
            if (field == value) return false;
            field = value;
            return true;
        }

        private static bool SetInt(ref int field, int value)
        {
            if (field == value) return false;
            field = value;
            return true;
        }

        public override bool GetBindingValueInternal(ref string _value, string _bindingName)
        {
            switch (_bindingName)
            {
                case "snapvisible": _value = visible ? "true" : "false"; return true;
                case "snapname": _value = name; return true;
                case "snaprole": _value = role; return true;
                case "snaphealth": _value = health; return true;
                case "snaphealthmax": _value = healthMax; return true;
                case "snapstamina": _value = stamina; return true;
                case "snapstaminamax": _value = staminaMax; return true;
                case "snapmoodword": _value = moodWord; return true;
                case "snapmoodicon": _value = moodIcon; return true;
                case "snapmoodcolor": _value = moodColor; return true;
                case "snaphasportrait": _value = hasPortrait ? "true" : "false"; return true;
                case "snapnoportrait": _value = hasPortrait ? "false" : "true"; return true;
                case "snapspecvisible": _value = specVisible ? "true" : "false"; return true;
                case "snapspecname": _value = specName; return true;
                case "snapspecicon": _value = specIcon; return true;
            }
            // trait<N> / trait<N>visible (N = 1..3) and sk<row>star<n> (row 0..4, n = 1..7: lit or dim)
            if (_bindingName.StartsWith("snaptrait", StringComparison.Ordinal) && _bindingName.Length >= 10)
            {
                int i = _bindingName[9] - '1';
                if (i >= 0 && i < TraitRows)
                {
                    _value = _bindingName.EndsWith("visible", StringComparison.Ordinal) ? (traitVisible[i] ? "true" : "false") : traits[i];
                    return true;
                }
            }
            if (_bindingName.StartsWith("snapsk", StringComparison.Ordinal) && _bindingName.Length == 12)
            {
                int row = _bindingName[6] - '0', star = _bindingName[11] - '0';
                if (row >= 0 && row < SkillRows && star >= 1 && star <= Member.MaxStars)
                {
                    _value = stars[row] >= star ? StarOn : StarOff;
                    return true;
                }
            }
            return base.GetBindingValueInternal(ref _value, _bindingName);
        }
    }
}
